BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_LOCAL_ACCOUNT (ID VARCHAR2(36 CHAR) PRIMARY KEY, USERNAME VARCHAR2(128 CHAR) NOT NULL UNIQUE, DISPLAY_NAME VARCHAR2(160 CHAR) NOT NULL, PASSWORD_HASH VARCHAR2(1024 CHAR) NOT NULL, MUST_CHANGE NUMBER(1) NOT NULL, STATUS VARCHAR2(16 CHAR) NOT NULL, FAILED_ATTEMPTS NUMBER(10) NOT NULL, LOCKED_UNTIL TIMESTAMP(6) WITH TIME ZONE, SECURITY_EPOCH NUMBER(19) NOT NULL, VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_IAM_LOCAL_USERNAME CHECK (REGEXP_LIKE(USERNAME,''^[a-z0-9][a-z0-9._@-]{2,127}$'')), CONSTRAINT CK_INX_IAM_LOCAL_CHANGE CHECK (MUST_CHANGE IN (0,1)), CONSTRAINT CK_INX_IAM_LOCAL_STATUS CHECK (STATUS IN (''ACTIVE'',''SUSPENDED'')), CONSTRAINT CK_INX_IAM_LOCAL_FAILED CHECK (FAILED_ATTEMPTS>=0), CONSTRAINT CK_INX_IAM_LOCAL_EPOCH CHECK (SECURITY_EPOCH>=0), CONSTRAINT CK_INX_IAM_LOCAL_VERSION CHECK (VERSION>=0), CONSTRAINT CK_INX_IAM_LOCAL_TIME CHECK (UPDATED_AT>=CREATED_AT AND (LOCKED_UNTIL IS NULL OR LOCKED_UNTIL>=CREATED_AT)), CONSTRAINT CK_INX_IAM_LOCAL_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_LOCAL_STATUS ON INFRANEXUM_IAM_LOCAL_ACCOUNT(STATUS,LOCKED_UNTIL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_LOCAL_SESSION (ID VARCHAR2(36 CHAR) PRIMARY KEY, ACCOUNT_ID VARCHAR2(36 CHAR) NOT NULL, TOKEN_HASH CHAR(64 CHAR) NOT NULL UNIQUE, CSRF_HASH CHAR(64 CHAR) NOT NULL, SECURITY_EPOCH NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_SEEN_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, IDLE_EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, ABSOLUTE_EXPIRES_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, REVOKED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT FK_INX_IAM_SESSION_ACCOUNT FOREIGN KEY(ACCOUNT_ID) REFERENCES INFRANEXUM_IAM_LOCAL_ACCOUNT(ID), CONSTRAINT CK_INX_IAM_SESSION_TOKEN CHECK (REGEXP_LIKE(TOKEN_HASH,''^[0-9a-f]{64}$'')), CONSTRAINT CK_INX_IAM_SESSION_CSRF CHECK (REGEXP_LIKE(CSRF_HASH,''^[0-9a-f]{64}$'')), CONSTRAINT CK_INX_IAM_SESSION_EPOCH CHECK (SECURITY_EPOCH>=0), CONSTRAINT CK_INX_IAM_SESSION_EXPIRY CHECK (LAST_SEEN_AT>=CREATED_AT AND IDLE_EXPIRES_AT>LAST_SEEN_AT AND IDLE_EXPIRES_AT<=ABSOLUTE_EXPIRES_AT AND ABSOLUTE_EXPIRES_AT>CREATED_AT AND (REVOKED_AT IS NULL OR REVOKED_AT>=CREATED_AT)), CONSTRAINT CK_INX_IAM_SESSION_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_SESSION_ACCOUNT ON INFRANEXUM_IAM_LOCAL_SESSION(ACCOUNT_ID,REVOKED_AT,ABSOLUTE_EXPIRES_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
